QURAN_LIB.push(
{"id": "q2-177", "s": "البقرة", "a": "177", "t": "ليس البر أن تولوا وجوهكم قبل المشرق والمغرب ولكن البر من آمن بالله واليوم الآخر والملائكة والكتاب والنبيين وآتى المال على حبه ذوي القربى واليتامى والمساكين وابن السبيل والسائلين وفي الرقاب وأقام الصلاة وآتى الزكاة والموفون بعهدهم إذا عاهدوا والصابرين في البأساء والضراء وحين البأس أولئك الذين صدقوا وأولئك هم المتقون", "th": ["charity", "patience", "trust_amanah"], "n": "البر ليس مظاهر، بل إيمان وعطاء ووفاء بالعهد وصبر في الشدة.", "kb": 1},
{"id": "q2-197", "s": "البقرة", "a": "197", "t": "الحج أشهر معلومات فمن فرض فيهن الحج فلا رفث ولا فسوق ولا جدال في الحج وما تفعلوا من خير يعلمه الله وتزودوا فإن خير الزاد التقوى واتقون يا أولي الألباب", "th": ["decision", "transition"], "n": "خير ما تحمله في رحلة الحياة التقوى؛ زاد لا ينفد.", "kb": 1},
{"id": "q2-208", "s": "البقرة", "a": "208", "t": "يا أيها الذين آمنوا ادخلوا في السلم كافة ولا تتبعوا خطوات الشيطان إنه لكم عدو مبين", "th": ["faith_weak", "argument"], "n": "الإسلام كلٌّ متكامل؛ والسلم مع النفس والناس جزء منه.", "kb": 1},
{"id": "q2-222", "s": "البقرة", "a": "222", "t": "ويسألونك عن المحيض قل هو أذى فاعتزلوا النساء في المحيض ولا تقربوهن حتى يطهرن فإذا تطهرن فأتوهن من حيث أمركم الله إن الله يحب التوابين ويحب المتطهرين", "th": ["sin", "despair"], "n": "الله يحب التوابين، أي الذين يعودون كلما أخطؤوا، لا الذين لا يخطئون فقط.", "kb": 1},
{"id": "q2-255", "s": "البقرة", "a": "255", "t": "الله لا إله إلا هو الحي القيوم لا تأخذه سنة ولا نوم له ما في السماوات وما في الأرض من ذا الذي يشفع عنده إلا بإذنه يعلم ما بين أيديهم وما خلفهم ولا يحيطون بشيء من علمه إلا بما شاء وسع كرسيه السماوات والأرض ولا يئوده حفظهما وهو العلي العظيم", "th": ["anxiety", "fear", "waswasa"], "n": "آية الكرسي: تعريف بالله الذي لا ينام ولا يعجزه حفظ شيء؛ تطمئن الخائف والقلق.", "kb": 1, "dua": true, "w": "في الصباح والمساء وعند النوم"},
{"id": "q2-261", "s": "البقرة", "a": "261", "t": "مثل الذين ينفقون أموالهم في سبيل الله كمثل حبة أنبتت سبع سنابل في كل سنبلة مائة حبة والله يضاعف لمن يشاء والله واسع عليم", "th": ["charity", "rizq"], "n": "العطاء يتضاعف عند الله أضعافًا لا يتخيلها الحساب البشري.", "kb": 1},
{"id": "q2-264", "s": "البقرة", "a": "264", "t": "يا أيها الذين آمنوا لا تبطلوا صدقاتكم بالمن والأذى كالذي ينفق ماله رئاء الناس ولا يؤمن بالله واليوم الآخر فمثله كمثل صفوان عليه تراب فأصابه وابل فتركه صلدا لا يقدرون على شيء مما كسبوا والله لا يهدي القوم الكافرين", "th": ["charity", "insult", "people_pleasing"], "n": "المنّ والأذى يُفسدان المعروف؛ أعطِ دون أن تذكّر الناس بعطائك.", "kb": 1},
{"id": "q2-282", "s": "البقرة", "a": "282", "t": "يا أيها الذين آمنوا إذا تداينتم بدين إلى أجل مسمى فاكتبوه وليكتب بينكم كاتب بالعدل ولا يأب كاتب أن يكتب كما علمه الله فليكتب وليملل الذي عليه الحق وليتق الله ربه ولا يبخس منه شيئا فإن كان الذي عليه الحق سفيها أو ضعيفا أو لا يستطيع أن يمل هو فليملل وليه بالعدل واستشهدوا شهيدين من رجالكم فإن لم يكونا رجلين فرجل وامرأتان ممن ترضون من الشهداء أن تضل إحداهما فتذكر إحداهما الأخرى ولا يأب الشهداء إذا ما دعوا ولا تسأموا أن تكتبوه صغيرا أو كبيرا إلى أجله ذلكم أقسط عند الله وأقوم للشهادة وأدنى ألا ترتابوا إلا أن تكون تجارة حاضرة تديرونها بينكم فليس عليكم جناح ألا تكتبوها وأشهدوا إذا تبايعتم ولا يضار كاتب ولا شهيد وإن تفعلوا فإنه فسوق بكم واتقوا الله ويعلمكم الله والله بكل شيء عليم", "th": ["debt", "trust_amanah", "friends"], "n": "توثيق الديون، حتى بين الأقارب والأصدقاء، حماية للعلاقة لا اتهام للثقة.", "kb": 1},
{"id": "q2-284", "s": "البقرة", "a": "284", "t": "لله ما في السماوات وما في الأرض وإن تبدوا ما في أنفسكم أو تخفوه يحاسبكم به الله فيغفر لمن يشاء ويعذب من يشاء والله على كل شيء قدير", "th": ["waswasa", "sin"], "n": "ما في النفوس يعلمه الله؛ والآيتان بعدها تخففان: لا يكلف الله نفسًا إلا وسعها.", "kb": 1},
{"id": "q3-14", "s": "آل عمران", "a": "14", "t": "زين للناس حب الشهوات من النساء والبنين والقناطير المقنطرة من الذهب والفضة والخيل المسومة والأنعام والحرث ذلك متاع الحياة الدنيا والله عنده حسن المآب", "th": ["desire", "rizq", "comparison"], "n": "حب المال والنساء والأولاد مزيّن في الفطرة؛ والمطلوب ترتيبه لا إنكاره.", "kb": 1},
{"id": "q3-31", "s": "آل عمران", "a": "31", "t": "قل إن كنتم تحبون الله فاتبعوني يحببكم الله ويغفر لكم ذنوبكم والله غفور رحيم", "th": ["faith_weak"], "n": "المحبة الحقيقية لله تظهر في الاتباع؛ والجزاء محبة الله ومغفرته.", "kb": 1},
{"id": "q3-92", "s": "آل عمران", "a": "92", "t": "لن تنالوا البر حتى تنفقوا مما تحبون وما تنفقوا من شيء فإن الله به عليم", "th": ["charity", "desire"], "n": "أعلى درجات العطاء أن تعطي مما تحبه، لا مما زاد عنك.", "kb": 1},
{"id": "q3-110", "s": "آل عمران", "a": "110", "t": "كنتم خير أمة أخرجت للناس تأمرون بالمعروف وتنهون عن المنكر وتؤمنون بالله ولو آمن أهل الكتاب لكان خيرا لهم منهم المؤمنون وأكثرهم الفاسقون", "th": ["leadership", "charity"], "n": "الخيرية مشروطة بالأمر بالمعروف والنهي عن المنكر؛ ليست امتيازًا بالنسب.", "kb": 1},
{"id": "q3-133", "s": "آل عمران", "a": "133", "t": "وسارعوا إلى مغفرة من ربكم وجنة عرضها السماوات والأرض أعدت للمتقين", "th": ["sin", "laziness", "hope"], "n": "دعوة إلى المسارعة: التأجيل في التوبة والخير يضيّع الفرص.", "kb": 1},
{"id": "q3-146", "s": "آل عمران", "a": "146", "t": "وكأين من نبي قاتل معه ربيون كثير فما وهنوا لما أصابهم في سبيل الله وما ضعفوا وما استكانوا والله يحب الصابرين", "th": ["patience", "despair", "burnout"], "n": "المؤمنون عبر التاريخ أصابهم ما يصيبك فلم يضعفوا ولم يستكينوا؛ والله يحب الصابرين.", "kb": 1},
{"id": "q3-154", "s": "آل عمران", "a": "154", "t": "ثم أنزل عليكم من بعد الغم أمنة نعاسا يغشى طائفة منكم وطائفة قد أهمتهم أنفسهم يظنون بالله غير الحق ظن الجاهلية يقولون هل لنا من الأمر من شيء قل إن الأمر كله لله يخفون في أنفسهم ما لا يبدون لك يقولون لو كان لنا من الأمر شيء ما قتلنا هاهنا قل لو كنتم في بيوتكم لبرز الذين كتب عليهم القتل إلى مضاجعهم وليبتلي الله ما في صدوركم وليمحص ما في قلوبكم والله عليم بذات الصدور", "th": ["anxiety", "fear", "emergency"], "n": "بعد الهم تأتي السكينة؛ حتى في أصعب المواقف ينزل الله أمانًا على القلوب.", "kb": 1},
{"id": "q3-186", "s": "آل عمران", "a": "186", "t": "لتبلون في أموالكم وأنفسكم ولتسمعن من الذين أوتوا الكتاب من قبلكم ومن الذين أشركوا أذى كثيرا وإن تصبروا وتتقوا فإن ذلك من عزم الأمور", "th": ["patience", "insult", "injustice"], "n": "الأذى من الناس جزء متوقع من الطريق؛ والصبر والتقوى من عزم الأمور.", "kb": 1},
{"id": "q3-190", "s": "آل عمران", "a": "190-191", "t": "إن في خلق السماوات والأرض واختلاف الليل والنهار لآيات لأولي الألباب * الذين يذكرون الله قياما وقعودا وعلى جنوبهم ويتفكرون في خلق السماوات والأرض ربنا ما خلقت هذا باطلا سبحانك فقنا عذاب النار", "th": ["faith_weak", "anxiety"], "n": "التأمل في الكون يعيد ترتيب الهموم ويقوّي الإيمان.", "kb": 1},
{"id": "q4-9", "s": "النساء", "a": "9", "t": "وليخش الذين لو تركوا من خلفهم ذرية ضعافا خافوا عليهم فليتقوا الله وليقولوا قولا سديدا", "th": ["parenting", "anxiety", "honesty"], "n": "الخوف على الأبناء يعالجه العدل والقول السديد اليوم، لا القلق وحده.", "kb": 1},
{"id": "q4-34", "s": "النساء", "a": "34", "t": "الرجال قوامون على النساء بما فضل الله بعضهم على بعض وبما أنفقوا من أموالهم فالصالحات قانتات حافظات للغيب بما حفظ الله واللاتي تخافون نشوزهن فعظوهن واهجروهن في المضاجع واضربوهن فإن أطعنكم فلا تبغوا عليهن سبيلا إن الله كان عليا كبيرا", "th": ["marriage"], "n": "القوامة مسؤولية ونفقة، لا تسلّط؛ والآية تُفهم مع آيات المعاشرة بالمعروف وأحاديث تحريم الإيذاء. ولتفاصيلها الفقهية يُرجع إلى أهل العلم.", "kb": 1},
{"id": "q4-79", "s": "النساء", "a": "79", "t": "ما أصابك من حسنة فمن الله وما أصابك من سيئة فمن نفسك وأرسلناك للناس رسولا وكفى بالله شهيدا", "th": ["sin", "decision", "despair"], "n": "الخير من الله، والسيئة تستدعي مراجعة النفس لا لوم الآخرين.", "kb": 1},
{"id": "q4-85", "s": "النساء", "a": "85", "t": "من يشفع شفاعة حسنة يكن له نصيب منها ومن يشفع شفاعة سيئة يكن له كفل منها وكان الله على كل شيء مقيتا", "th": ["charity", "friends", "work"], "n": "التوسط في الخير لك نصيب منه، والتوسط في الشر عليك وزره.", "kb": 1},
{"id": "q4-104", "s": "النساء", "a": "104", "t": "ولا تهنوا في ابتغاء القوم إن تكونوا تألمون فإنهم يألمون كما تألمون وترجون من الله ما لا يرجون وكان الله عليما حكيما", "th": ["patience", "despair", "burnout"], "n": "إن كنت تتألم فغيرك يتألم كذلك؛ والفرق الرجاء في الله.", "kb": 1},
{"id": "q4-123", "s": "النساء", "a": "123", "t": "ليس بأمانيكم ولا أماني أهل الكتاب من يعمل سوءا يجز به ولا يجد له من دون الله وليا ولا نصيرا", "th": ["honesty", "sin", "laziness"], "n": "الأماني وحدها لا تكفي؛ العمل هو ما يُحاسب عليه الإنسان.", "kb": 1},
{"id": "q4-149", "s": "النساء", "a": "149", "t": "إن تبدوا خيرا أو تخفوه أو تعفوا عن سوء فإن الله كان عفوا قديرا", "th": ["forgive", "revenge"], "n": "العفو مع القدرة صفة من صفات الله؛ وقبلها رخصة الجهر بالظلم لمن ظُلم.", "kb": 1},
{"id": "q5-32", "s": "المائدة", "a": "32", "t": "من أجل ذلك كتبنا على بني إسرائيل أنه من قتل نفسا بغير نفس أو فساد في الأرض فكأنما قتل الناس جميعا ومن أحياها فكأنما أحيا الناس جميعا ولقد جاءتهم رسلنا بالبينات ثم إن كثيرا منهم بعد ذلك في الأرض لمسرفون", "th": ["despair", "injustice"], "n": "قيمة النفس الواحدة كقيمة البشرية كلها؛ ونفسك أنت منها.", "kb": 1},
{"id": "q5-54", "s": "المائدة", "a": "54", "t": "يا أيها الذين آمنوا من يرتد منكم عن دينه فسوف يأتي الله بقوم يحبهم ويحبونه أذلة على المؤمنين أعزة على الكافرين يجاهدون في سبيل الله ولا يخافون لومة لائم ذلك فضل الله يؤتيه من يشاء والله واسع عليم", "th": ["faith_weak", "self_worth", "people_pleasing"], "n": "من صفات من يحبهم الله: لا يخافون لومة لائم؛ علاج لإرضاء الناس.", "kb": 1},
{"id": "q5-87", "s": "المائدة", "a": "87", "t": "يا أيها الذين آمنوا لا تحرموا طيبات ما أحل الله لكم ولا تعتدوا إن الله لا يحب المعتدين", "th": ["burnout", "desire"], "n": "التشدد في حرمان النفس من المباح ليس تقوى؛ الاعتدال من الدين.", "kb": 1},
{"id": "q5-105", "s": "المائدة", "a": "105", "t": "يا أيها الذين آمنوا عليكم أنفسكم لا يضركم من ضل إذا اهتديتم إلى الله مرجعكم جميعا فينبئكم بما كنتم تعملون", "th": ["boundaries", "people_pleasing", "different_belief"], "n": "مسؤوليتك عن نفسك أولًا؛ ضلال غيرك لا يضرك إذا اهتديت وأديت ما عليك.", "kb": 1},
{"id": "q6-59", "s": "الأنعام", "a": "59", "t": "وعنده مفاتح الغيب لا يعلمها إلا هو ويعلم ما في البر والبحر وما تسقط من ورقة إلا يعلمها ولا حبة في ظلمات الأرض ولا رطب ولا يابس إلا في كتاب مبين", "th": ["anxiety", "fear", "decision"], "n": "الغيب عند الله؛ والقلق من المستقبل يخف حين تتذكر أن لا ورقة تسقط إلا بعلمه.", "kb": 1},
{"id": "q6-70", "s": "الأنعام", "a": "70", "t": "وذر الذين اتخذوا دينهم لعبا ولهوا وغرتهم الحياة الدنيا وذكر به أن تبسل نفس بما كسبت ليس لها من دون الله ولي ولا شفيع وإن تعدل كل عدل لا يؤخذ منها أولئك الذين أبسلوا بما كسبوا لهم شراب من حميم وعذاب أليم بما كانوا يكفرون", "th": ["friends", "different_belief", "digital"], "n": "أعرض عن مجالس السخرية من الدين دون صدام، وذكّر بهدوء.", "kb": 1},
{"id": "q6-108", "s": "الأنعام", "a": "108", "t": "ولا تسبوا الذين يدعون من دون الله فيسبوا الله عدوا بغير علم كذلك زينا لكل أمة عملهم ثم إلى ربهم مرجعهم فينبئهم بما كانوا يعملون", "th": ["different_belief", "argument", "insult"], "n": "حتى في الخلاف العقدي لا مكان للسب؛ فالسب يجرّ سبًّا أشد.", "kb": 1},
{"id": "q6-151", "s": "الأنعام", "a": "151", "t": "قل تعالوا أتل ما حرم ربكم عليكم ألا تشركوا به شيئا وبالوالدين إحسانا ولا تقتلوا أولادكم من إملاق نحن نرزقكم وإياهم ولا تقربوا الفواحش ما ظهر منها وما بطن ولا تقتلوا النفس التي حرم الله إلا بالحق ذلكم وصاكم به لعلكم تعقلون", "th": ["poverty", "parenting", "rizq"], "n": "الخوف من الفقر لا يبرر ظلم الأبناء؛ الرزق مكفول من الله.", "kb": 1},
{"id": "q7-31", "s": "الأعراف", "a": "31", "t": "يا بني آدم خذوا زينتكم عند كل مسجد وكلوا واشربوا ولا تسرفوا إنه لا يحب المسرفين", "th": ["addiction", "rizq", "illness"], "n": "الاعتدال في الأكل والإنفاق قاعدة صحية ومالية وإيمانية.", "kb": 1},
{"id": "q7-55", "s": "الأعراف", "a": "55", "t": "ادعوا ربكم تضرعا وخفية إنه لا يحب المعتدين", "th": ["hope", "faith_weak"], "n": "الدعاء الخاشع الخفي أقرب إلى القلب وأبعد عن الرياء.", "kb": 1},
{"id": "q7-201", "s": "الأعراف", "a": "201", "t": "إن الذين اتقوا إذا مسهم طائف من الشيطان تذكروا فإذا هم مبصرون", "th": ["waswasa", "anger", "desire"], "n": "عند الوسوسة أو اندفاع الغضب: التذكر يعيد البصيرة.", "kb": 1},
{"id": "q8-2", "s": "الأنفال", "a": "2", "t": "إنما المؤمنون الذين إذا ذكر الله وجلت قلوبهم وإذا تليت عليهم آياته زادتهم إيمانا وعلى ربهم يتوكلون", "th": ["faith_weak"], "n": "علامات الإيمان الحي: قلب يتأثر، وإيمان يزيد، وتوكل على الله.", "kb": 1},
{"id": "q8-28", "s": "الأنفال", "a": "28", "t": "واعلموا أنما أموالكم وأولادكم فتنة وأن الله عنده أجر عظيم", "th": ["parenting", "rizq"], "n": "المال والأولاد اختبار؛ والنجاح فيه بالتوازن لا بالتعلق.", "kb": 1},
{"id": "q8-61", "s": "الأنفال", "a": "61", "t": "وإن جنحوا للسلم فاجنح لها وتوكل على الله إنه هو السميع العليم", "th": ["argument", "forgive", "leadership"], "n": "إذا مال الطرف الآخر إلى الصلح فاقبله وتوكل على الله.", "kb": 1},
{"id": "q9-91", "s": "التوبة", "a": "91", "t": "ليس على الضعفاء ولا على المرضى ولا على الذين لا يجدون ما ينفقون حرج إذا نصحوا لله ورسوله ما على المحسنين من سبيل والله غفور رحيم", "th": ["illness", "burnout", "self_worth"], "n": "لا لوم على الضعيف والمريض والعاجز إذا نصح وأخلص؛ العذر مقبول.", "kb": 1},
{"id": "q9-119", "s": "التوبة", "a": "119", "t": "يا أيها الذين آمنوا اتقوا الله وكونوا مع الصادقين", "th": ["honesty", "friends"], "n": "الصحبة الصادقة تحميك؛ اختر أصدقاءك من أهل الصدق.", "kb": 1},
{"id": "q10-44", "s": "يونس", "a": "44", "t": "إن الله لا يظلم الناس شيئا ولكن الناس أنفسهم يظلمون", "th": ["injustice", "despair"], "n": "الله لا يظلم أحدًا؛ ومراجعة النفس أولى من اتهام القدر.", "kb": 1},
{"id": "q10-107", "s": "يونس", "a": "107", "t": "وإن يمسسك الله بضر فلا كاشف له إلا هو وإن يردك بخير فلا راد لفضله يصيب به من يشاء من عباده وهو الغفور الرحيم", "th": ["illness", "rizq", "anxiety"], "n": "الضر والخير بيد الله؛ فلا تتعلق بغيره خوفًا ولا رجاءً.", "kb": 1},
{"id": "q11-61", "s": "هود", "a": "61", "t": "وإلى ثمود أخاهم صالحا قال يا قوم اعبدوا الله ما لكم من إله غيره هو أنشأكم من الأرض واستعمركم فيها فاستغفروه ثم توبوا إليه إن ربي قريب مجيب", "th": ["work", "transition"], "n": "الإنسان مستخلف لعمارة الأرض؛ العمل النافع عبادة.", "kb": 1},
{"id": "q11-123", "s": "هود", "a": "123", "t": "ولله غيب السماوات والأرض وإليه يرجع الأمر كله فاعبده وتوكل عليه وما ربك بغافل عما تعملون", "th": ["anxiety", "decision"], "n": "الأمر كله لله؛ فاعبده وتوكل عليه ودع ما لا تملكه.", "kb": 1},
{"id": "q12-64", "s": "يوسف", "a": "64", "t": "قال هل آمنكم عليه إلا كما أمنتكم على أخيه من قبل فالله خير حافظا وهو أرحم الراحمين", "th": ["parenting", "fear", "anxiety"], "n": "قالها يعقوب وهو يرسل ابنه بعد فقد يوسف؛ عند الخوف على الأبناء يُسلَّم حفظهم لله.", "kb": 1},
{"id": "q12-83", "s": "يوسف", "a": "83", "t": "قال بل سولت لكم أنفسكم أمرا فصبر جميل عسى الله أن يأتيني بهم جميعا إنه هو العليم الحكيم", "th": ["grief", "patience", "hope"], "n": "الصبر الجميل لا يمنع الأمل؛ يعقوب صبر وهو يرجو اللقاء.", "kb": 1},
{"id": "q12-111", "s": "يوسف", "a": "111", "t": "لقد كان في قصصهم عبرة لأولي الألباب ما كان حديثا يفترى ولكن تصديق الذي بين يديه وتفصيل كل شيء وهدى ورحمة لقوم يؤمنون", "th": ["patience", "faith_weak"], "n": "قصص الأنبياء ليست حكايات، بل دروس لمواقف تشبه مواقفنا.", "kb": 1},
{"id": "q13-22", "s": "الرعد", "a": "22", "t": "والذين صبروا ابتغاء وجه ربهم وأقاموا الصلاة وأنفقوا مما رزقناهم سرا وعلانية ويدرءون بالحسنة السيئة أولئك لهم عقبى الدار", "th": ["patience", "forgive", "revenge"], "n": "صفات أهل العاقبة الحسنة: الصبر لله، والعطاء، ودفع السيئة بالحسنة.", "kb": 1},
{"id": "q14-34", "s": "إبراهيم", "a": "34", "t": "وآتاكم من كل ما سألتموه وإن تعدوا نعمت الله لا تحصوها إن الإنسان لظلوم كفار", "th": ["gratitude", "comparison"], "n": "نِعَم الله أكثر من أن تُحصى؛ والتركيز على النقص ظلم للنفس.", "kb": 1},
{"id": "q15-88", "s": "الحجر", "a": "88", "t": "لا تمدن عينيك إلى ما متعنا به أزواجا منهم ولا تحزن عليهم واخفض جناحك للمؤمنين", "th": ["comparison", "envy", "digital"], "n": "لا تُطِل النظر إلى ما عند الآخرين؛ المقارنة تسرق الرضا.", "kb": 1},
{"id": "q16-18", "s": "النحل", "a": "18", "t": "وإن تعدوا نعمة الله لا تحصوها إن الله لغفور رحيم", "th": ["gratitude"], "n": "مع كثرة النعم، الله غفور رحيم بتقصيرنا في شكرها.", "kb": 1},
{"id": "q16-53", "s": "النحل", "a": "53", "t": "وما بكم من نعمة فمن الله ثم إذا مسكم الضر فإليه تجأرون", "th": ["gratitude", "emergency", "despair"], "n": "كل نعمة من الله؛ والإنسان يلجأ إليه في الشدة، فلا ينسَه في الرخاء.", "kb": 1},
{"id": "q16-91", "s": "النحل", "a": "91", "t": "وأوفوا بعهد الله إذا عاهدتم ولا تنقضوا الأيمان بعد توكيدها وقد جعلتم الله عليكم كفيلا إن الله يعلم ما تفعلون", "th": ["trust_amanah", "honesty"], "n": "الوفاء بالعهد عبادة؛ والأيمان لا تُنقض بعد توكيدها.", "kb": 1},
{"id": "q16-128", "s": "النحل", "a": "128", "t": "إن الله مع الذين اتقوا والذين هم محسنون", "th": ["hope", "patience"], "n": "معية الله للمتقين والمحسنين؛ هذا يكفي سندًا.", "kb": 1},
{"id": "q17-11", "s": "الإسراء", "a": "11", "t": "ويدع الإنسان بالشر دعاءه بالخير وكان الإنسان عجولا", "th": ["anger", "decision", "despair"], "n": "الإنسان عجول، قد يدعو على نفسه وقت الضيق؛ فتمهل.", "kb": 1},
{"id": "q17-37", "s": "الإسراء", "a": "37", "t": "ولا تمش في الأرض مرحا إنك لن تخرق الأرض ولن تبلغ الجبال طولا", "th": ["arrogance", "self_worth"], "n": "التواضع: لن تخرق الأرض ولن تبلغ الجبال طولًا.", "kb": 1},
{"id": "q17-70", "s": "الإسراء", "a": "70", "t": "ولقد كرمنا بني آدم وحملناهم في البر والبحر ورزقناهم من الطيبات وفضلناهم على كثير ممن خلقنا تفضيلا", "th": ["self_worth", "insult"], "n": "كرامة الإنسان ثابتة من الله؛ لا يملك أحد أن يسلبها.", "kb": 1},
{"id": "q17-80", "s": "الإسراء", "a": "80", "t": "وقل رب أدخلني مدخل صدق وأخرجني مخرج صدق واجعل لي من لدنك سلطانا نصيرا", "th": ["transition", "decision"], "n": "دعاء لكل بداية ونهاية: أن يكون دخولك وخروجك صادقين، ومعك سند من الله.", "kb": 1, "dua": true, "w": "عند بداية جديدة"},
{"id": "q17-84", "s": "الإسراء", "a": "84", "t": "قل كل يعمل على شاكلته فربكم أعلم بمن هو أهدى سبيلا", "th": ["different_belief", "argument", "boundaries"], "n": "لكل إنسان طريقته؛ والله أعلم بمن هو أهدى، فلا داعي لإجبار الآخرين.", "kb": 1},
{"id": "q20-2", "s": "طه", "a": "2-3", "t": "ما أنزلنا عليك القرآن لتشقى * إلا تذكرة لمن يخشى", "th": ["sadness", "burnout", "faith_weak"], "n": "القرآن لم ينزل ليشقى الإنسان؛ الدين رحمة لا عبء.", "kb": 1},
{"id": "q20-114", "s": "طه", "a": "114", "t": "فتعالى الله الملك الحق ولا تعجل بالقرآن من قبل أن يقضى إليك وحيه وقل رب زدني علما", "th": ["study"], "n": "دعاء الطالب: طلب الزيادة من العلم، والتواضع أمام ما لا نعرف.", "kb": 1, "dua": true, "w": "عند الدراسة"},
{"id": "q21-35", "s": "الأنبياء", "a": "35", "t": "كل نفس ذائقة الموت ونبلوكم بالشر والخير فتنة وإلينا ترجعون", "th": ["death_fear", "patience", "grief"], "n": "الخير والشر كلاهما اختبار؛ والموت حقيقة تعيد ترتيب الأولويات.", "kb": 1},
{"id": "q22-46", "s": "الحج", "a": "46", "t": "أفلم يسيروا في الأرض فتكون لهم قلوب يعقلون بها أو آذان يسمعون بها فإنها لا تعمى الأبصار ولكن تعمى القلوب التي في الصدور", "th": ["faith_weak", "sin"], "n": "العمى الحقيقي عمى القلب؛ والقلب يُستشفى بالتدبر.", "kb": 1},
{"id": "q23-1", "s": "المؤمنون", "a": "1-5", "t": "بسم الله الرحمن الرحيم قد أفلح المؤمنون * الذين هم في صلاتهم خاشعون * والذين هم عن اللغو معرضون * والذين هم للزكاة فاعلون * والذين هم لفروجهم حافظون", "th": ["faith_weak", "desire", "gossip"], "n": "صفات المفلحين: الخشوع، والإعراض عن اللغو، والعفة؛ برنامج عملي للحياة.", "kb": 1},
{"id": "q23-8", "s": "المؤمنون", "a": "8", "t": "والذين هم لأماناتهم وعهدهم راعون", "th": ["trust_amanah", "honesty", "work"], "n": "رعاية الأمانات والعهود من صفات المؤمنين المفلحين.", "kb": 1},
{"id": "q23-96", "s": "المؤمنون", "a": "96", "t": "ادفع بالتي هي أحسن السيئة نحن أعلم بما يصفون", "th": ["forgive", "revenge", "insult"], "n": "قابل الإساءة بالأحسن؛ وهذا لا يعني القبول بالظلم المستمر.", "kb": 1},
{"id": "q24-26", "s": "النور", "a": "26", "t": "الخبيثات للخبيثين والخبيثون للخبيثات والطيبات للطيبين والطيبون للطيبات أولئك مبرءون مما يقولون لهم مغفرة ورزق كريم", "th": ["marriage_seek", "slander"], "n": "الطيبون للطيبات؛ والآية نزلت في براءة عائشة، تطمئن من يُتهم ظلمًا في عرضه.", "kb": 1},
{"id": "q24-27", "s": "النور", "a": "27", "t": "يا أيها الذين آمنوا لا تدخلوا بيوتا غير بيوتكم حتى تستأنسوا وتسلموا على أهلها ذلكم خير لكم لعلكم تذكرون", "th": ["boundaries", "neighbors", "digital"], "n": "الاستئذان أدب يحمي الخصوصية؛ وينطبق اليوم على الرسائل والهواتف أيضًا.", "kb": 1},
{"id": "q24-28", "s": "النور", "a": "28", "t": "فإن لم تجدوا فيها أحدا فلا تدخلوها حتى يؤذن لكم وإن قيل لكم ارجعوا فارجعوا هو أزكى لكم والله بما تعملون عليم", "th": ["boundaries"], "n": "إذا رُفض الاستئذان فارجع دون غضب؛ احترام حدود الآخرين أزكى لك.", "kb": 1},
{"id": "q25-72", "s": "الفرقان", "a": "72", "t": "والذين لا يشهدون الزور وإذا مروا باللغو مروا كراما", "th": ["gossip", "digital", "friends"], "n": "المرور الكريم على اللغو والجدل الفارغ، بدل الانجرار إليه.", "kb": 1},
{"id": "q28-77", "s": "القصص", "a": "77", "t": "وابتغ فيما آتاك الله الدار الآخرة ولا تنس نصيبك من الدنيا وأحسن كما أحسن الله إليك ولا تبغ الفساد في الأرض إن الله لا يحب المفسدين", "th": ["rizq", "work", "burnout"], "n": "لا تنس نصيبك من الدنيا؛ التوازن بين الطموح والآخرة والإحسان.", "kb": 1},
{"id": "q29-57", "s": "العنكبوت", "a": "57", "t": "كل نفس ذائقة الموت ثم إلينا ترجعون", "th": ["death_fear", "grief"], "n": "الموت حقيقة مشتركة، والرجوع إلى الله يمنحه معنى.", "kb": 1},
{"id": "q29-60", "s": "العنكبوت", "a": "60", "t": "وكأين من دابة لا تحمل رزقها الله يرزقها وإياكم وهو السميع العليم", "th": ["rizq", "anxiety", "ghurba"], "n": "كم من مخلوق لا يحمل رزقه والله يرزقه؛ ومن هاجر أو سافر فالله يرزقه.", "kb": 1},
{"id": "q30-22", "s": "الروم", "a": "22", "t": "ومن آياته خلق السماوات والأرض واختلاف ألسنتكم وألوانكم إن في ذلك لآيات للعالمين", "th": ["different_belief", "ghurba", "self_worth"], "n": "اختلاف الألسنة والألوان آية من آيات الله، لا سبب للتفاضل أو الاحتقار.", "kb": 1},
{"id": "q30-41", "s": "الروم", "a": "41", "t": "ظهر الفساد في البر والبحر بما كسبت أيدي الناس ليذيقهم بعض الذي عملوا لعلهم يرجعون", "th": ["injustice", "sin"], "n": "ما يصيب الأرض من فساد بسبب أفعال البشر؛ والغاية الرجوع.", "kb": 1},
{"id": "q31-22", "s": "لقمان", "a": "22", "t": "ومن يسلم وجهه إلى الله وهو محسن فقد استمسك بالعروة الوثقى وإلى الله عاقبة الأمور", "th": ["decision", "hope"], "n": "الاستسلام لله مع الإحسان أوثق ما يتمسك به الإنسان.", "kb": 1},
{"id": "q31-34", "s": "لقمان", "a": "34", "t": "إن الله عنده علم الساعة وينزل الغيث ويعلم ما في الأرحام وما تدري نفس ماذا تكسب غدا وما تدري نفس بأي أرض تموت إن الله عليم خبير", "th": ["anxiety", "death_fear", "decision"], "n": "ما سيحدث غدًا لا يعلمه أحد؛ فاعمل ما عليك اليوم ودع الغد لله.", "kb": 1},
{"id": "q33-35", "s": "الأحزاب", "a": "35", "t": "إن المسلمين والمسلمات والمؤمنين والمؤمنات والقانتين والقانتات والصادقين والصادقات والصابرين والصابرات والخاشعين والخاشعات والمتصدقين والمتصدقات والصائمين والصائمات والحافظين فروجهم والحافظات والذاكرين الله كثيرا والذاكرات أعد الله لهم مغفرة وأجرا عظيما", "th": ["self_worth", "faith_weak"], "n": "الرجال والنساء سواء في الأجر والمكانة عند الله.", "kb": 1},
{"id": "q33-41", "s": "الأحزاب", "a": "41-42", "t": "يا أيها الذين آمنوا اذكروا الله ذكرا كثيرا * وسبحوه بكرة وأصيلا", "th": ["anxiety", "faith_weak"], "n": "ذكر الله الكثير يربط اليوم كله به، فيخف القلق.", "kb": 1, "dua": true, "w": "ذكر يومي"},
{"id": "q33-58", "s": "الأحزاب", "a": "58", "t": "والذين يؤذون المؤمنين والمؤمنات بغير ما اكتسبوا فقد احتملوا بهتانا وإثما مبينا", "th": ["slander", "insult", "injustice"], "n": "إيذاء الناس بما لم يفعلوا بهتان وإثم مبين.", "kb": 1},
{"id": "q35-8", "s": "فاطر", "a": "8", "t": "أفمن زين له سوء عمله فرآه حسنا فإن الله يضل من يشاء ويهدي من يشاء فلا تذهب نفسك عليهم حسرات إن الله عليم بما يصنعون", "th": ["sadness", "parenting", "kin"], "n": "لا تُهلك نفسك حسرة على من لم يهتد؛ عليك البلاغ والهداية من الله.", "kb": 1},
{"id": "q35-18", "s": "فاطر", "a": "18", "t": "ولا تزر وازرة وزر أخرى وإن تدع مثقلة إلى حملها لا يحمل منه شيء ولو كان ذا قربى إنما تنذر الذين يخشون ربهم بالغيب وأقاموا الصلاة ومن تزكى فإنما يتزكى لنفسه وإلى الله المصير", "th": ["sin", "boundaries", "parents"], "n": "لا يحمل أحد ذنب غيره؛ أنت مسؤول عن عملك لا عن أخطاء أهلك.", "kb": 1},
{"id": "q39-9", "s": "الزمر", "a": "9", "t": "أمن هو قانت آناء الليل ساجدا وقائما يحذر الآخرة ويرجو رحمة ربه قل هل يستوي الذين يعلمون والذين لا يعلمون إنما يتذكر أولو الألباب", "th": ["study", "self_worth"], "n": "العلم يرفع صاحبه؛ والمتأمل الخائف الراجي غير الغافل.", "kb": 1},
{"id": "q39-23", "s": "الزمر", "a": "23", "t": "الله نزل أحسن الحديث كتابا متشابها مثاني تقشعر منه جلود الذين يخشون ربهم ثم تلين جلودهم وقلوبهم إلى ذكر الله ذلك هدى الله يهدي به من يشاء ومن يضلل الله فما له من هاد", "th": ["faith_weak", "sadness"], "n": "القرآن تلين له القلوب والجلود؛ استماعه علاج لقسوة القلب.", "kb": 1},
{"id": "q40-55", "s": "غافر", "a": "55", "t": "فاصبر إن وعد الله حق واستغفر لذنبك وسبح بحمد ربك بالعشي والإبكار", "th": ["patience", "hope", "despair"], "n": "وعد الله حق؛ فاصبر واستغفر وسبّح، والفرج آتٍ.", "kb": 1},
{"id": "q41-46", "s": "فصلت", "a": "46", "t": "من عمل صالحا فلنفسه ومن أساء فعليها وما ربك بظلام للعبيد", "th": ["sin", "people_pleasing"], "n": "عملك لك أو عليك؛ لا ينتظر الله منك شيئًا لنفسه.", "kb": 1},
{"id": "q42-30", "s": "الشورى", "a": "30", "t": "وما أصابكم من مصيبة فبما كسبت أيديكم ويعفو عن كثير", "th": ["sin", "patience"], "n": "بعض المصائب من أعمالنا، والله يعفو عن كثير؛ فهي دعوة إلى المراجعة لا إلى جلد الذات.", "kb": 1},
{"id": "q42-36", "s": "الشورى", "a": "36", "t": "فما أوتيتم من شيء فمتاع الحياة الدنيا وما عند الله خير وأبقى للذين آمنوا وعلى ربهم يتوكلون", "th": ["rizq", "comparison"], "n": "ما عند الله خير وأبقى؛ المتاع الدنيوي مؤقت.", "kb": 1},
{"id": "q43-32", "s": "الزخرف", "a": "32", "t": "أهم يقسمون رحمت ربك نحن قسمنا بينهم معيشتهم في الحياة الدنيا ورفعنا بعضهم فوق بعض درجات ليتخذ بعضهم بعضا سخريا ورحمت ربك خير مما يجمعون", "th": ["rizq", "comparison", "envy"], "n": "تفاوت الأرزاق قسمة من الله لحكمة؛ يخدم الناس بعضهم بعضًا.", "kb": 1},
{"id": "q45-23", "s": "الجاثية", "a": "23", "t": "أفرأيت من اتخذ إلهه هواه وأضله الله على علم وختم على سمعه وقلبه وجعل على بصره غشاوة فمن يهديه من بعد الله أفلا تذكرون", "th": ["desire", "addiction"], "n": "اتباع الهوى بلا ضابط يُعمي البصيرة؛ والهوى قد يصير معبودًا.", "kb": 1},
{"id": "q47-7", "s": "محمد", "a": "7", "t": "يا أيها الذين آمنوا إن تنصروا الله ينصركم ويثبت أقدامكم", "th": ["hope", "patience", "oppressor_power"], "n": "من وقف مع الحق ثبّته الله.", "kb": 1},
{"id": "q48-4", "s": "الفتح", "a": "4", "t": "هو الذي أنزل السكينة في قلوب المؤمنين ليزدادوا إيمانا مع إيمانهم ولله جنود السماوات والأرض وكان الله عليما حكيما", "th": ["anxiety", "fear", "faith_weak"], "n": "السكينة تُنزَّل من الله؛ اطلبها بالدعاء والذكر.", "kb": 1},
{"id": "q49-9", "s": "الحجرات", "a": "9", "t": "وإن طائفتان من المؤمنين اقتتلوا فأصلحوا بينهما فإن بغت إحداهما على الأخرى فقاتلوا التي تبغي حتى تفيء إلى أمر الله فإن فاءت فأصلحوا بينهما بالعدل وأقسطوا إن الله يحب المقسطين", "th": ["argument", "kin", "leadership"], "n": "الإصلاح بين المتخاصمين واجب، بالعدل لا بالمجاملة.", "kb": 1},
{"id": "q51-56", "s": "الذاريات", "a": "56", "t": "وما خلقت الجن والإنس إلا ليعبدون", "th": ["despair", "transition", "faith_weak"], "n": "سؤال «لماذا أنا هنا؟» له جواب: العبودية التي تشمل العمل والعلاقات والرحمة.", "kb": 1},
{"id": "q52-48", "s": "الطور", "a": "48", "t": "واصبر لحكم ربك فإنك بأعيننا وسبح بحمد ربك حين تقوم", "th": ["patience", "loneliness", "sadness"], "n": "«فإنك بأعيننا»: لست وحدك في صبرك، الله يرعاك.", "kb": 1},
{"id": "q55-13", "s": "الرحمن", "a": "13", "t": "فبأي آلاء ربكما تكذبان", "th": ["gratitude"], "n": "سؤال يتكرر ليوقظ الشعور بالنعم.", "kb": 1},
{"id": "q57-16", "s": "الحديد", "a": "16", "t": "ألم يأن للذين آمنوا أن تخشع قلوبهم لذكر الله وما نزل من الحق ولا يكونوا كالذين أوتوا الكتاب من قبل فطال عليهم الأمد فقست قلوبهم وكثير منهم فاسقون", "th": ["faith_weak", "sin"], "n": "دعوة رقيقة لمن طال عليه الفتور: ألم يحن الوقت؟", "kb": 1},
{"id": "q58-11", "s": "المجادلة", "a": "11", "t": "يا أيها الذين آمنوا إذا قيل لكم تفسحوا في المجالس فافسحوا يفسح الله لكم وإذا قيل انشزوا فانشزوا يرفع الله الذين آمنوا منكم والذين أوتوا العلم درجات والله بما تعملون خبير", "th": ["study", "self_worth", "boundaries"], "n": "التفسح في المجالس أدب، والرفعة الحقيقية بالإيمان والعلم.", "kb": 1},
{"id": "q59-19", "s": "الحشر", "a": "19", "t": "ولا تكونوا كالذين نسوا الله فأنساهم أنفسهم أولئك هم الفاسقون", "th": ["faith_weak", "self_worth"], "n": "نسيان الله ينتهي إلى نسيان النفس؛ والعودة إليه عودة إلى الذات.", "kb": 1},
{"id": "q63-9", "s": "المنافقون", "a": "9", "t": "يا أيها الذين آمنوا لا تلهكم أموالكم ولا أولادكم عن ذكر الله ومن يفعل ذلك فأولئك هم الخاسرون", "th": ["work", "parenting", "burnout"], "n": "الانشغال بالعمل والأبناء طبيعي، لكن لا يجوز أن يطغى على علاقتك بالله.", "kb": 1},
{"id": "q64-15", "s": "التغابن", "a": "15", "t": "إنما أموالكم وأولادكم فتنة والله عنده أجر عظيم", "th": ["rizq", "parenting"], "n": "المال والأولاد اختبار؛ والأجر العظيم عند الله.", "kb": 1},
{"id": "q64-16", "s": "التغابن", "a": "16", "t": "فاتقوا الله ما استطعتم واسمعوا وأطيعوا وأنفقوا خيرا لأنفسكم ومن يوق شح نفسه فأولئك هم المفلحون", "th": ["burnout", "laziness", "sin"], "n": "المطلوب منك ما تستطيع، لا الكمال؛ هذه الآية ترفع عنك عبء المثالية.", "kb": 1},
{"id": "q70-19", "s": "المعارج", "a": "19-22", "t": "إن الإنسان خلق هلوعا * إذا مسه الشر جزوعا * وإذا مسه الخير منوعا * إلا المصلين", "th": ["anxiety", "fear", "rizq"], "n": "الجزع والمنع طبع بشري؛ والصلاة الدائمة تعالجه.", "kb": 1},
{"id": "q73-10", "s": "المزمل", "a": "10", "t": "واصبر على ما يقولون واهجرهم هجرا جميلا", "th": ["insult", "boundaries", "patience"], "n": "الهجر الجميل: ابتعاد هادئ عن المؤذي بلا انتقام ولا تجريح.", "kb": 1},
{"id": "q75-14", "s": "القيامة", "a": "14-15", "t": "بل الإنسان على نفسه بصيرة * ولو ألقى معاذيره", "th": ["honesty", "sin"], "n": "الإنسان يعرف نفسه مهما برّر؛ الصدق مع النفس بداية الإصلاح.", "kb": 1},
{"id": "q84-6", "s": "الانشقاق", "a": "6", "t": "يا أيها الإنسان إنك كادح إلى ربك كدحا فملاقيه", "th": ["burnout", "work", "patience"], "n": "الحياة كدح وتعب، لكنه كدح له غاية: لقاء الله.", "kb": 1},
{"id": "q89-15", "s": "الفجر", "a": "15-16", "t": "فأما الإنسان إذا ما ابتلاه ربه فأكرمه ونعمه فيقول ربي أكرمن * وأما إذا ما ابتلاه فقدر عليه رزقه فيقول ربي أهانن", "th": ["rizq", "poverty", "self_worth"], "n": "السعة ليست إكرامًا دائمًا، والضيق ليس إهانة؛ كلاهما ابتلاء.", "kb": 1},
{"id": "q90-4", "s": "البلد", "a": "4", "t": "لقد خلقنا الإنسان في كبد", "th": ["burnout", "patience", "despair"], "n": "المشقة جزء من طبيعة الحياة؛ وجود الصعوبة لا يعني أنك أخطأت الطريق.", "kb": 1},
{"id": "q92-4", "s": "الليل", "a": "4-7", "t": "إن سعيكم لشتى * فأما من أعطى واتقى * وصدق بالحسنى * فسنيسره لليسرى", "th": ["work", "charity", "decision"], "n": "السعي يختلف، ومن أعطى واتقى يسّر الله له طريقه.", "kb": 1},
{"id": "q93-6", "s": "الضحى", "a": "6-8", "t": "ألم يجدك يتيما فآوى * ووجدك ضالا فهدى * ووجدك عائلا فأغنى", "th": ["gratitude", "despair", "loneliness"], "n": "تذكير النبي ﷺ بماضيه: كان يتيمًا فآواه الله؛ تذكّر كيف حُفظت من قبل.", "kb": 1},
{"id": "q94-1", "s": "الشرح", "a": "1-4", "t": "بسم الله الرحمن الرحيم ألم نشرح لك صدرك * ووضعنا عنك وزرك * الذي أنقض ظهرك * ورفعنا لك ذكرك", "th": ["sadness", "burnout", "hope"], "n": "انشراح الصدر ورفع الأثقال من الله؛ وبعدها مباشرة: إن مع العسر يسرًا.", "kb": 1},
{"id": "q94-7", "s": "الشرح", "a": "7-8", "t": "فإذا فرغت فانصب * وإلى ربك فارغب", "th": ["work", "burnout", "faith_weak"], "n": "إذا انتهيت من مهمة فانتقل إلى أخرى، واجعل رغبتك إلى الله.", "kb": 1},
{"id": "q95-4", "s": "التين", "a": "4", "t": "لقد خلقنا الإنسان في أحسن تقويم", "th": ["self_worth", "illness"], "n": "الإنسان مخلوق في أحسن صورة؛ قيمتك لا تنقص بمرض أو مظهر.", "kb": 1},
{"id": "q99-7", "s": "الزلزلة", "a": "7-8", "t": "فمن يعمل مثقال ذرة خيرا يره * ومن يعمل مثقال ذرة شرا يره", "th": ["hope", "sin", "charity"], "n": "لا يضيع شيء: الخير الصغير يُرى، والشر الصغير كذلك.", "kb": 1},
{"id": "q102-1", "s": "التكاثر", "a": "1-2", "t": "بسم الله الرحمن الرحيم ألهاكم التكاثر * حتى زرتم المقابر", "th": ["comparison", "rizq", "digital"], "n": "التنافس على الكثرة يُلهي حتى آخر العمر؛ انتبه لما يستهلك حياتك.", "kb": 1},
{"id": "q104-1", "s": "الهمزة", "a": "1", "t": "بسم الله الرحمن الرحيم ويل لكل همزة لمزة", "th": ["gossip", "insult", "slander"], "n": "الغمز واللمز والسخرية من الناس ذنب يتوعده الله.", "kb": 1},
{"id": "q107-1", "s": "الماعون", "a": "1-7", "t": "بسم الله الرحمن الرحيم أرأيت الذي يكذب بالدين * فذلك الذي يدع اليتيم * ولا يحض على طعام المسكين * فويل للمصلين * الذين هم عن صلاتهم ساهون * الذين هم يراءون * ويمنعون الماعون", "th": ["charity", "people_pleasing", "poverty"], "n": "قسوة على اليتيم وبخل بالمعروف ورياء: صفات تتعارض مع حقيقة الدين.", "kb": 1},
{"id": "q108-1", "s": "الكوثر", "a": "1-3", "t": "بسم الله الرحمن الرحيم إنا أعطيناك الكوثر * فصل لربك وانحر * إن شانئك هو الأبتر", "th": ["insult", "sadness", "hope"], "n": "نزلت حين عُيّر النبي ﷺ بفقد أبنائه؛ الله يعطي الخير الكثير، والمبغض هو الأبتر.", "kb": 1},
{"id": "q110-1", "s": "النصر", "a": "1-3", "t": "بسم الله الرحمن الرحيم إذا جاء نصر الله والفتح * ورأيت الناس يدخلون في دين الله أفواجا * فسبح بحمد ربك واستغفره إنه كان توابا", "th": ["gratitude", "arrogance", "sin"], "n": "عند النجاح: التسبيح والاستغفار بدل الغرور.", "kb": 1},
{"id": "q112-1", "s": "الإخلاص", "a": "1-4", "t": "بسم الله الرحمن الرحيم قل هو الله أحد * الله الصمد * لم يلد ولم يولد * ولم يكن له كفوا أحد", "th": ["faith_weak", "waswasa", "anxiety"], "n": "التوحيد الخالص يحرر القلب من التعلق بغير الله.", "kb": 1, "dua": true, "w": "في الصباح والمساء"}
);
